import axios from 'axios';


const API_URL = 'http://localhost:5000/api/places';

export const fetchPlaces = async (filters) => {
    try {
        const response = await axios.get('http://localhost:5000/api/places', { params: filters });
        return response.data;
    } catch (error) {
        console.error('Error fetching places:', error);
        throw error;
    }
};

app.get('/api/places/:id', async (req, res) => {
    const { id } = req.params;
    try {
        const place = await db.findPlaceById(id); // Assuming `findPlaceById` is a function that fetches a place by id.
        if (!place) {
            return res.status(404).json({ message: 'Place not found' });
        }
        res.json(place);
    } catch (error) {
        console.error('Error fetching place:', error);
        res.status(500).json({ message: 'Server error' });
    }
});
